// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// The Inventory's on-screen part, client only. The 1 key (a bag touch button on phones) or the Bag button in the
// right HUD column opens the bag window, where the player takes one kind out into their hand (to carry it to a Work
// Station, say) or puts what they hold into the bag; the same key closes it. On desktop the cursor is captured for
// the camera, and scene UI cannot be clicked while it is, so the window frees it while open and captures it again on
// close if it was. A "+1 Wood" notice says when a script adds to the player's bag. The Inventory prefab mounts it;
// the rules and the script API live in ./inventory.
//
//   mountInventoryHud({ title: 'Bag', storeVerb: 'Store', takeVerb: 'Take out', emptyText: 'Nothing here yet' })
import ReactEcs, { UiEntity } from '@dcl/sdk/react-ecs'
import { InputAction, PointerEventType, PointerLock, engine, inputSystem } from '@dcl/sdk/ecs'
import { isMobile } from '@dcl/sdk/platform'
import { actionIcon } from './actionIcons'
import { heldBy } from './carry'
import { addHudItem, declareTouchButtons } from './hudLayout'
import { sayNotice } from './interactPrompt'
import { askInventory, bagOf, myWallet, onInventory, roomFor, type InventoryAct } from './inventory'
import { bagTotal } from './pure/inventoryRules'
import { ThemedEntity, UiButton, UiText, uiSizes } from './uiComponents'
import { sceneUiTheme } from './uiTheme'
import { mountWindow } from './uiWindow'

export interface InventoryHudText {
  title: string
  storeVerb: string
  takeVerb: string
  emptyText: string
}

const OPEN_KEY = InputAction.IA_ACTION_3

interface HudState { open: boolean; busy: boolean; relock: boolean }

function cursorLocked(): boolean {
  return PointerLock.getOrNull(engine.CameraEntity)?.isPointerLocked === true
}

function openBag(state: HudState): void {
  if (state.open) return
  state.open = true
  state.relock = !isMobile() && cursorLocked()
  if (state.relock) PointerLock.createOrReplace(engine.CameraEntity, { isPointerLocked: false })
}

function closeBag(state: HudState): void {
  if (!state.open) return
  state.open = false
  if (state.relock) PointerLock.createOrReplace(engine.CameraEntity, { isPointerLocked: true })
  state.relock = false
}

function ask(state: HudState, act: InventoryAct): void {
  if (state.busy) return
  state.busy = true
  void askInventory(act).then((answer) => {
    state.busy = false
    if (!answer.ok && answer.message !== '') sayNotice(answer.message)
  })
}

function BagButton(props: { text: InventoryHudText; state: HudState }) {
  const theme = sceneUiTheme()
  const size = uiSizes('hud')
  const total = bagTotal(bagOf(myWallet()))
  const phone = isMobile()
  const label = phone ? `${props.text.title}  ${total}` : `${props.text.title}  ${total}   [1]`
  const width = phone ? 200 : 220
  return <ThemedEntity uiTransform={{ elementId: 'inventory-button', width, height: size.button, flexDirection: 'row', alignItems: 'center',
    borderRadius: theme.radius, flexShrink: 0, pointerFilter: 'block' }}
    uiBackground={{ color: theme.surface }} onMouseDown={() => openBag(props.state)}>
    <UiText value={label} color={theme.text} size={size.text} height={size.button} align="middle-center" uiTransform={{ width }} />
  </ThemedEntity>
}

// Every box here has a fixed width and height worked out from the rows it holds: the renderer does not grow an
// auto-height panel around its children, so a window sized by its content draws only its header.
function windowLayout(rows: number) {
  const size = uiSizes('window')
  const phone = isMobile()
  const width = phone ? 900 : 560
  const inner = width - 2 * size.pad
  const header = size.button
  const row = Math.max(size.button, 56)
  const shown = Math.min(rows, phone ? 4 : 8)
  const list = shown === 0 ? row : shown * row + (shown - 1) * size.gap
  const more = rows > shown ? Math.round(size.small * 1.6) : 0
  const height = 2 * size.pad + header + size.gap + list + more + size.gap + size.primary
  return { size, width, inner, header, row, shown, list, more, height }
}

function BagRow(props: { kind: string; count: number; hint: string; disabled: boolean; width: number; height: number; onPress(): void }) {
  const theme = sceneUiTheme()
  const size = uiSizes('window')
  const textWidth = props.width - 2 * size.pad
  return <ThemedEntity uiTransform={{ width: props.width, height: props.height, flexShrink: 0, flexDirection: 'row', alignItems: 'center',
    padding: { left: size.pad, right: size.pad }, borderRadius: theme.radius, pointerFilter: 'block' }}
    uiBackground={{ color: props.disabled ? theme.panel : theme.surface }} onMouseDown={() => { if (!props.disabled) props.onPress() }}>
    <UiText value={props.kind} color={props.disabled ? theme.muted : theme.text} size={size.text} height={props.height}
      uiTransform={{ width: Math.round(textWidth * 0.45), flexShrink: 0 }} />
    <UiText value={`×${props.count}`} color={theme.text} size={size.text} height={props.height} mono align="middle-right"
      uiTransform={{ width: Math.round(textWidth * 0.2), flexShrink: 0 }} />
    <UiText value={props.hint} color={theme.muted} size={size.small} height={props.height} align="middle-right"
      uiTransform={{ width: textWidth - Math.round(textWidth * 0.45) - Math.round(textWidth * 0.2), flexShrink: 0 }} />
  </ThemedEntity>
}

function BagWindow(props: { text: InventoryHudText; state: HudState }) {
  const me = myWallet()
  const bag = bagOf(me)
  const held = me === '' ? null : heldBy(me)
  const canStore = held !== null && roomFor(me, held.kind) >= 1
  const theme = sceneUiTheme()
  const layout = windowLayout(bag.length)
  const { size, inner } = layout
  const close = () => closeBag(props.state)
  return <ThemedEntity uiTransform={{ elementId: 'inventory', width: layout.width, height: layout.height, flexShrink: 0, flexDirection: 'column',
    padding: size.pad, borderRadius: theme.radius, borderWidth: 1, borderColor: theme.border, pointerFilter: 'block' }} uiBackground={{ color: theme.panel }}>
    <UiEntity uiTransform={{ width: inner, height: layout.header, flexShrink: 0, flexDirection: 'row', alignItems: 'center', pointerFilter: 'none' }}>
      <UiText value={props.text.title} color={theme.text} size={size.title} height={layout.header}
        uiTransform={{ width: inner - layout.header, flexShrink: 0, elementId: 'inventory-title' }} />
      <UiButton theme={theme} label="X" secondary onClick={close}
        uiTransform={{ width: layout.header, height: layout.header, flexShrink: 0, elementId: 'inventory-close' }} />
    </UiEntity>
    <UiEntity uiTransform={{ width: inner, height: layout.list + layout.more, flexShrink: 0, flexDirection: 'column', margin: { top: size.gap }, pointerFilter: 'none' }}>
      {bag.length === 0
        ? <UiText value={props.text.emptyText} color={theme.muted} size={size.text} height={layout.row} uiTransform={{ width: inner }} />
        : bag.slice(0, layout.shown).map((entry, i) => <UiEntity key={entry.kind} uiTransform={{ width: inner, height: layout.row, flexShrink: 0,
          margin: { top: i === 0 ? 0 : size.gap }, pointerFilter: 'none' }}>
          <BagRow kind={entry.kind} count={entry.count} hint={held === null ? props.text.takeVerb : ''} width={inner} height={layout.row}
            disabled={held !== null || props.state.busy} onPress={() => ask(props.state, { type: 'take', kind: entry.kind })} />
        </UiEntity>)}
      {layout.more > 0 && <UiText value={`+${bag.length - layout.shown}`} color={theme.muted} size={size.small} height={layout.more} uiTransform={{ width: inner }} />}
    </UiEntity>
    <UiButton theme={theme} label={held === null ? props.text.storeVerb : `${props.text.storeVerb} ${held.kind}`}
      disabled={!canStore || props.state.busy} onClick={() => ask(props.state, { type: 'store' })}
      uiTransform={{ elementId: 'inventory-store', width: inner, height: size.primary, flexShrink: 0, margin: { top: size.gap } }} />
  </ThemedEntity>
}

/** Mounts the Bag button, window, key and touch button; returns their removal. */
export function mountInventoryHud(text: InventoryHudText): () => void {
  const state: HudState = { open: false, busy: false, relock: false }
  const toggle = () => {
    if (!inputSystem.isTriggered(OPEN_KEY, PointerEventType.PET_DOWN)) return
    if (state.open) closeBag(state)
    else openBag(state)
  }
  engine.addSystem(toggle, undefined, 'runtime-inventory-key')
  const removals = [
    addHudItem('right', () => <BagButton text={text} state={state} />, { order: -30 }),
    mountWindow({ open: () => state.open, close: () => closeBag(state), render: () => <BagWindow text={text} state={state} /> }),
    declareTouchButtons([{ action: OPEN_KEY, icon: actionIcon('bag') }, { action: InputAction.IA_JUMP, icon: actionIcon('jump') }]),
    onInventory((event) => {
      if (event.type === 'add' && event.player === myWallet()) sayNotice(`+${event.count} ${event.kind}`)
    })
  ]
  return () => {
    engine.removeSystem(toggle)
    for (const remove of removals) remove()
  }
}
